-- BTS (2 ans après le bac, tous les domaines) : huit métiers de technicien deviennent accessibles avec un BTS. Idempotent.
UPDATE "job" SET "level" = 'QUALIFIE', "descFr" = 'Délivrer les médicaments sur ordonnance et conseiller les patients. Demande un BTS ou plus en pharmacie ou en santé.', "descEn" = 'Dispense prescribed drugs and advise patients. Requires a BTS or higher in pharmacy or health.' WHERE "id" = 'preparateur_pharma';
UPDATE "job" SET "level" = 'QUALIFIE', "descFr" = 'Conseiller les producteurs sur les semences, le compost et les récoltes. Demande un BTS ou plus en agronomie.', "descEn" = 'Advise farmers on seeds, compost and harvests. Requires a BTS or higher in agronomy.' WHERE "id" = 'technicien_agricole';
UPDATE "job" SET "level" = 'QUALIFIE', "descFr" = 'Accueillir les clients, gérer les arrivées, les départs et les réservations. Demande un BTS ou plus en hôtellerie.', "descEn" = 'Welcome guests and handle check-ins, check-outs and bookings. Requires a BTS or higher in hospitality.' WHERE "id" = 'receptionniste';
UPDATE "job" SET "level" = 'QUALIFIE', "descFr" = 'Établir les déclarations en douane des conteneurs au port. Demande un BTS ou plus en logistique ou en droit.', "descEn" = 'Prepare customs declarations for containers at the port. Requires a BTS or higher in logistics or law.' WHERE "id" = 'declarant_douane';
UPDATE "job" SET "level" = 'QUALIFIE', "descFr" = 'Entretenir portiques, chariots et moteurs du port. Demande un BTS ou plus en mécanique.', "descEn" = 'Service cranes, forklifts and engines at the port. Requires a BTS or higher in mechanics.' WHERE "id" = 'technicien_maintenance';
UPDATE "job" SET "level" = 'QUALIFIE', "descFr" = 'Recruter, préparer les contrats et suivre les congés. Demande un BTS ou plus en ressources humaines.', "descEn" = 'Recruit, prepare contracts and track leave. Requires a BTS or higher in HR.' WHERE "id" = 'assistant_rh';
UPDATE "job" SET "level" = 'QUALIFIE', "descFr" = 'Contrôler la collecte des déchets, les caniveaux et l’eau potable de la commune. Demande un BTS ou plus en environnement.', "descEn" = 'Check waste collection, drains and drinking water for the town. Requires a BTS or higher in environment.' WHERE "id" = 'technicien_assainissement';
UPDATE "job" SET "level" = 'QUALIFIE', "descFr" = 'Dessiner les plans des bâtiments à l’échelle pour le bureau d’études. Demande un BTS ou plus en architecture ou en BTP.', "descEn" = 'Draw scale building plans for the design office. Requires a BTS or higher in architecture or construction.' WHERE "id" = 'dessinateur_projeteur';
